local KTool = CS.Engine.Lib.KTool

local TaskCellNodePath = 'Game.Activity.RegressionActivity.Cell.RegressionTaskCellNodeNew'
local IDType = typeof(CS.Game.Native.Common.ID)
---@type RegressionUtils
local RegressionUtils = import('Game.Activity.RegressionActivity.RegressionUtils')

--- from: Assets/BundleResources/Prefabs/RegressionNew/RegressionNewTaskPanel5010.prefab > name: RegressionNewTaskPanel5010
---@class RegressionNewTaskPanel
---@field Env                            RegressionNewTaskPanel
---@field controller                        Engine.Modules.LuaBehaviour
---@field TextProgress                    UnityEngine.RectTransform                @ 0
---@field 1                                UnityEngine.RectTransform                @ 1
---@field 2                                UnityEngine.RectTransform                @ 2
---@field 3                                UnityEngine.RectTransform                @ 3
---@field 4                                UnityEngine.RectTransform                @ 4
---@field 5                                UnityEngine.RectTransform                @ 5
---@field 6                                UnityEngine.RectTransform                @ 6
---@field DayView                        UnityEngine.RectTransform                @ 7
---@field BtnDayNode                        UnityEngine.RectTransform                @ 8
---@field LayoutDayGroup                    UnityEngine.RectTransform                @ 9
---@field ListView                        SuperScrollView.LoopGridView                @ 10
local RegressionNewTaskPanel = Class('RegressionNewTaskPanel')

function RegressionNewTaskPanel:__init()
    ---@type RegressionActivityMgr
    self.regressMgr = nil
    self.selectedDay = 1
end

function RegressionNewTaskPanel:__delete()
    self.selectedDay = 0
    self.regressMgr = nil
end

function RegressionNewTaskPanel:Awake()
    self.regressMgr = RegressionUtils.GetRegressMgr()
end

function RegressionNewTaskPanel:RefreshTopGoods()
    CfUtils.RefreshTopGoods({Constants.Currency.FreeDiamondId})
end

function RegressionNewTaskPanel:Refresh(config)
    if isNotNull(config) then
        self.config = config
    end
    ---@type RegressionDojo
    local homeDojo = self.regressMgr:GetHomeDojo()
    if homeDojo then
        self.goodsId = checkInt(homeDojo.taskInfo.activeValue)
        ---@type BackpackComponent
        local backpackComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.BackpackComponent)
        if backpackComponent then
            backpackComponent.backpack[tostring(self.goodsId)] = checkNumber(homeDojo.taskInfo.point)
        end
        ---计算当前已解锁的最大的天
        self.selectedDay = isNull(self.selectedDay) and checkNumber(self.regressMgr:GetTaskMaxUnlockGroupId()) or self.selectedDay
        self.tasks = self.regressMgr:GetTasksByGroup(self.selectedDay)
        self:FreshBoxUI()
        ---更新任务列相关数据
        self:FreshTaskUI()
    end
end

function RegressionNewTaskPanel:FreshTaskUI()
    ---@type RegressionDojo
    local homeDojo = self.regressMgr:GetHomeDojo()
    if homeDojo then
        local groups = self.regressMgr:GetTaskGroups()
        KTool.DestroyGameObjectChildren(self.LayoutDayGroup.gameObject, true)
        local maxDay = self.regressMgr:GetTaskMaxUnlockGroupId()
        for i = 1, #groups do
            local day = groups[i]
            local go = KTool.Instantiate(self.LayoutDayGroup.gameObject, self.BtnDayNode.gameObject, true)
            CfUtils.SetActive(go, true)
            SetButtonAction(go, function()
                self:OnTaskGroupButtonAction(day)
            end)
            CfUtils.SetUISwitchText(go.transform:Find("ImgBg/TextNumber"), 1)
            if self.regressMgr:HasTaskGroupDawned(day) then
                CfUtils.SetUISwitchImage(go.transform:Find("ImgBg"), 3)
            elseif day == self.selectedDay then
                CfUtils.SetUISwitchImage(go.transform:Find("ImgBg"), 2)
                CfUtils.SetUISwitchText(go.transform:Find("ImgBg/TextNumber"), 2)
            else
                CfUtils.SetUISwitchImage(go.transform:Find("ImgBg"), 1)
            end
            CfUtils.SetUISwitchText(go.transform:Find("ImgBg/TextDay"), day == self.selectedDay and 2 or 1)
            CfUtils.FillText(go.transform:Find("ImgBg/TextNumber"), day)
            CfUtils.SetActive(go.transform:Find("Lock"), day > maxDay)
            CfUtils.SetActive(go.transform:Find("UnLock"), day <= maxDay)
            if day <= maxDay then
                CfUtils.SetActive(go.transform:Find("UnLock/ImgComplete"), self.regressMgr:HasTaskGroupDawned(day))
                local pro, max = self.regressMgr:GetTaskGroupProgress(day)
                --- progress
                CfUtils.FillText(go.transform:Find("UnLock/TextNumber"), string.format("%d/%d", pro, max))
                CfUtils.SetActive(go.transform:Find("UnLock/TextNumber"), true)
                CfUtils.SetUISwitchText(go.transform:Find("UnLock/TextNumber"), day == self.selectedDay and 2 or 1)
                local hasRed = self.regressMgr:HasRedPointGroupByDay(day)
                CfUtils.SetActive(go.transform:Find("CommonRedPoint"), hasRed)
                ---发送小红点事件的逻辑
            end
        end
        self:ReloadData()
    end
end

function RegressionNewTaskPanel:ReloadData()
    if not self.ListView.IsListViewInit then
        self.ListView:InitGridView(#self.tasks, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ListView, 0)
        GameUtils.ReloadData(self.ListView, #self.tasks)
    end
end

function RegressionNewTaskPanel:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local cell = loopListView:NewListViewItem("TaskCell")
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
    end
    -- 这里一个cell是一个页面，一个页面有9个按钮
    local data = self.tasks[index + 1]
    if isNotNull(data) then
        ---@type RegressionTaskCellNodeNew
        local env = CfUtils.GetLuaScr(cell, TaskCellNodePath)
        if env then
            env:SetBtnCallBackGet(Bind(self, self.OnCellAction))
            env:FreshBaseUI(data, self.goodsId)
        end
    end
    return cell
end

function RegressionNewTaskPanel:OnCellAction(cellData)
    if checkNumber(cellData.status) == 1 then
        ---可领取的情况下
        GameUtils.Request("newRegress/taskRewardDraw", {taskId = cellData.taskId}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                local rewards = response.data.rewards
                GoodsUtils.DrawRewards(rewards,true)
                ---更新界面ui
                self.regressMgr:UpdateTaskStatus(self.selectedDay, cellData.taskId, 2) ----已领取的逻辑
                CfUtils.DialogOpen(Constants.UITypeIds.UICommonRewardPop, { rewards = rewards })
                RegressionUtils.RefreshRedPoint(self.config.type)
                self:Refresh(self.config)
            end
        end)
    end
end

function RegressionNewTaskPanel:OnTaskGroupButtonAction(day)
    if self.selectedDay == day then
        return
    end
    local maxDay = self.regressMgr:GetTaskMaxUnlockGroupId()
    if day > maxDay then
        GameUtils.Toast(localize('暂未解锁'))
        return
    end
    self.selectedDay = day
    self.tasks = self.regressMgr:GetTasksByGroup(self.selectedDay)
    self:FreshTaskUI()
end

function RegressionNewTaskPanel:FreshBoxUI()
    ---@type RegressionDojo
    local homeDojo = self.regressMgr:GetHomeDojo()
    if homeDojo then
        CfUtils.FillText(self.TextProgress, checkNumber(homeDojo.taskInfo.point))
        local goodsConfMgr = GoodsConfMgr:GetInstance()
        local goodVo = goodsConfMgr:GetGoodsVoById(checkInt(homeDojo.taskInfo.activeValue))
        if goodVo then
            CfUtils.FillImage(self.TextProgress.transform:Find("ImgIcon"), goodVo.photoPath)
        end
        local box = homeDojo.taskInfo.taskBox
        if #box < 6 then
            for i = #box + 1, 6 do
                local boxGo = self[tostring(i)]
                if not isNull(boxGo) then
                    CfUtils.SetActive(boxGo, false)
                end
            end
        end
        for i, v in pairs(box) do
            local boxGo = self[tostring(i)]
            if not isNull(boxGo) then
                local idComp = KTool.GetOrAddComponent(boxGo.gameObject, IDType)
                idComp.id = i ---位置信息
                local reward = table.takeFirst(v.rewards)
                local vo = goodsConfMgr:GetGoodsVoById(reward.goodsId)
                if checkNumber(v.status) == 2 then
                    CfUtils.SetUISwitchImage(boxGo.transform:Find("ImgBg"), 1)
                elseif checkNumber(v.status) == 1 then
                    CfUtils.SetUISwitchImage(boxGo.transform:Find("ImgBg"), 3)
                else
                    CfUtils.SetUISwitchImage(boxGo.transform:Find("ImgBg"), 2)
                end
                CfUtils.SetActive(boxGo.transform:Find("ImgGet"), checkNumber(v.status) == 2)
                ---已领取的逻辑
                CfUtils.SetActive(boxGo.transform:Find("UIFX_RewardGlow"), checkNumber(v.status) == 1)
                ---可领取的逻辑
                CfUtils.FillImage(boxGo.transform:Find("ImgIcon"), vo.photoPath, true)
                CfUtils.SetUISwitchImage(boxGo.transform:Find("ImgIcon"), checkNumber(v.status) == 2 and 2 or 1)
                if not isNull(box[i - 1]) then
                    ---当前节点的前一个节点不为空的情况下
                    local preV = box[i - 1]
                    CfUtils.SetUISwitchImage(boxGo.transform:Find("coin/ImgBgCoin/ImgLine"), checkNumber(preV.status) == 2 and 1 or 2)
                    CfUtils.SetUISwitchImage(boxGo.transform:Find("coin/ImgBgCoin/ImgDot"), checkNumber(preV.status) == 2 and 1 or 2)
                else
                    CfUtils.SetUISwitchImage(boxGo.transform:Find("coin/ImgBgCoin/ImgLine"), checkNumber(v.status) == 2 and 1 or 2)
                    CfUtils.SetUISwitchImage(boxGo.transform:Find("coin/ImgBgCoin/ImgDot"), checkNumber(v.status) == 2 and 1 or 2)
                end

                CfUtils.FillText(boxGo.transform:Find("TxtNum"), "X" .. tostring(reward.num))
                CfUtils.FillText(boxGo.transform:Find("coin/TxtNumCoin"), tostring(v.unlockPoint))
                if goodVo then
                    CfUtils.FillImage(boxGo.transform:Find("coin/TxtNumCoin/ImgCoin"), goodVo.photoPath)
                end
                ---添加按钮事件的逻辑
                SetButtonAction(boxGo, function(event)
                    ---@type UnityEngine.EventSystems.PointerEventData
                    idComp = KTool.GetOrAddComponent(event.pointerClick, IDType)
                    local idx = idComp.id
                    local boxData = box[idx]
                    if boxData and checkNumber(boxData.status) == 1 then
                        ---可领取的情况下
                        GameUtils.Request("newRegress/drawTaskBox", { boxId = boxData.id }, function(request, response)
                            if checkNumber(response.errCode) == 0 then
                                local rewards = response.data.rewards
                                self.regressMgr:UpdateTaskBoxStatus(boxData.id, 2)
                                GoodsUtils.DrawRewards(rewards, true)
                                RegressionUtils.RefreshRedPoint(self.config.type)
                                self:Refresh(self.config)
                                ---刷新界面
                                ---更新界面ui
                                CfUtils.DialogOpen(Constants.UITypeIds.UICommonRewardPop, { rewards = rewards })
                            end
                        end)
                    else
                        GameUtils.Toast(checkNumber(boxData.status) == 2 and localize("当前奖励已领取") or localize('当前不可领取'))
                    end
                end)
            end
        end
    end
end

function RegressionNewTaskPanel:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return RegressionNewTaskPanel